import math
def calculate_electric_field(q, r):
    k = 8.99e9  # Coulomb's constant in N m^2 C^-2
    return k * q / (r ** 2)

def calculate_electric_potential(q, r):
    k = 8.99e9  # Coulomb's constant in N m^2 C^-2
    return k * q / r

